(7107684, 1084132, 96751, '<td valign="top">A great choice, but for me, this isn''t as powerful or dynamic as the original. Also, the tonal compression is just too strong for me, as is the orange hue over everything. Finally, this image appears static, while the original is characterized by highly dynamic movement.</td>', 'A great choice, but for me, this isn''t as powerful or dynamic as the original. Also, the tonal compression is just too strong for me, as is the orange hue over everything. Finally, this image appears static, while the original is characterized by highly dynamic movement.', '2013-09-27 14:38:25.000000', NULL, 1),
(7107685, 1084070, 96751, '<td valign="top">Very faithful recreation. I can''t decide if the straight on angle is better than the original, angled capture.</td>', 'Very faithful recreation. I can''t decide if the straight on angle is better than the original, angled capture.', '2013-09-27 14:40:06.000000', NULL, 1),
(7107686, 1083476, 96751, '<td valign="top">Awwww.  Except for a bit of oversharpening, this is a nice interpretation</td>', 'Awwww.  Except for a bit of oversharpening, this is a nice interpretation', '2013-09-27 14:41:22.000000', NULL, 1),
(7107687, 1084105, 96751, '<td valign="top">A very interesting interpretation of Christoph''s DQ. I love the cutout Magritte, and feel that is an improvement on the original, but I''m not sure about the exploding glass. Love her dress!!</td>', 'A very interesting interpretation of Christoph''s DQ. I love the cutout Magritte, and feel that is an improvement on the original, but I''m not sure about the exploding glass. Love her dress!!', '2013-09-27 14:42:52.000000', NULL, 1),
(7107689, 1084094, 96751, '<td valign="top">A beautiful heron, but sadly, neither the same species or quality of the original. Very soft focus for a wildlife photo, flat lighting, bland colors, and an obstructing, blurry foreground</td>', 'A beautiful heron, but sadly, neither the same species or quality of the original. Very soft focus for a wildlife photo, flat lighting, bland colors, and an obstructing, blurry foreground', '2013-09-27 14:45:45.000000', NULL, 1),
(7107690, 1084122, 96751, '<td valign="top">Incredibly faithful recreation.</td>', 'Incredibly faithful recreation.', '2013-09-27 14:46:03.000000', NULL, 1),
(7107695, 1083865, 96751, '<td valign="top">Good job! Technically, I think this would have worked better if the camera were level rather than slightly below eye level. And the highlights are a bit blown on the camera left side of the face, and camera right side of the cubp</td>', 'Good job! Technically, I think this would have worked better if the camera were level rather than slightly below eye level. And the highlights are a bit blown on the camera left side of the face, and camera right side of the cubp', '2013-09-27 14:48:59.000000', NULL, 1),
(7107699, 1084151, 96751, '<td valign="top">One of the images I was going to try for this challenge, which I ended up not entering. Very beautiful and technically wonderful recreation. Tiny nit might be that the strand on the right looks a bit oversharpened.</td>', 'One of the images I was going to try for this challenge, which I ended up not entering. Very beautiful and technically wonderful recreation. Tiny nit might be that the strand on the right looks a bit oversharpened.', '2013-09-27 14:50:36.000000', NULL, 1),
(7107700, 1084093, 96751, '<td valign="top">Wonderful recreation. Another of the ones I was contemplating for the challenge, which I ended up not entering.</td>', 'Wonderful recreation. Another of the ones I was contemplating for the challenge, which I ended up not entering.', '2013-09-27 14:51:17.000000', NULL, 1),
(7107701, 1084115, 96751, '<td valign="top">Beautiful image. And in my mind a great improvement over the original.</td>', 'Beautiful image. And in my mind a great improvement over the original.', '2013-09-27 14:52:18.000000', NULL, 1),
