(7107707, 1084120, 96751, '<td valign="top">Very cool, although I feel this image features the fabulous boulders in the foreground than the tower up top</td>', 'Very cool, although I feel this image features the fabulous boulders in the foreground than the tower up top', '2013-09-27 14:56:17.000000', NULL, 1),
(7107710, 1083470, 96751, '<td valign="top">Not sure which DQ''d image this is inspired by, but this reminds me of cutout''s wonderful work.</td>', 'Not sure which DQ''d image this is inspired by, but this reminds me of cutout''s wonderful work.', '2013-09-27 14:57:14.000000', NULL, 1),
(7107711, 1084084, 96751, '<td valign="top">What a wonderful photograph. The vignetting is a bit odd, however, especially over the hand, where it makes the skin look a bit grayish. It also makes the thumb the brightest spot in the image. I''d have loved a bit of dodging on the face and eyes.</td>', 'What a wonderful photograph. The vignetting is a bit odd, however, especially over the hand, where it makes the skin look a bit grayish. It also makes the thumb the brightest spot in the image. I''d have loved a bit of dodging on the face and eyes.', '2013-09-27 14:58:52.000000', NULL, 1),
(7107712, 1084156, 96751, '<td valign="top">Ha! Seeking redemption, Samantha?  It''s likely you''ll get it. Congrats on your ribbon.</td>', 'Ha! Seeking redemption, Samantha?  It''s likely you''ll get it. Congrats on your ribbon.', '2013-09-27 15:00:36.000000', NULL, 1),
